// internal/distributed/proxy/httpserver/handler.go line 335-346
func (h *Handlers) handleInsert(c *gin.Context) (interface{}, error) {
	wrappedReq := WrappedInsertRequest{}
	err := shouldBind(c, &wrappedReq)
	if err != nil {
		return nil, fmt.Errorf("%w: parse body failed: %v", errBadRequest, err)
	}
	req, err := wrappedReq.AsInsertRequest()
	if err != nil {
		return nil, fmt.Errorf("%w: convert body to pb failed: %v", errBadRequest, err)
	}
	return h.proxy.Insert(c, req)  // NO ENTITY COUNT VALIDATION HERE
}

// internal/proxy/task_insert.go line 120-125
maxInsertSize := Params.QuotaConfig.MaxInsertSize.GetAsInt()
if maxInsertSize != -1 && it.insertMsg.Size() > maxInsertSize {
	log.Ctx(ctx).Warn("insert request size exceeds maxInsertSize",
		zap.Int("request size", it.insertMsg.Size()), zap.Int("maxInsertSize", maxInsertSize))
	return merr.WrapErrAsInputError(merr.WrapErrParameterTooLarge("insert request size exceeds maxInsertSize"))
}
// NOTE: This validates BYTE SIZE (it.insertMsg.Size()), NOT ENTITY COUNT

// configs/milvus.yaml
maxInsertSize: -1  # maximum size of a single insert request, in bytes, -1 means no limit
// NOTE: Config is about byte size, not entity count
